// ─── File: DbOwnershipDemo.java ───
// Runnable demo contrasting shared-database vs database-per-service.

import java.math.BigDecimal;
import java.util.*;
import java.util.function.Consumer;
import java.util.logging.*;

public class DbOwnershipDemo {

    private static final Logger log = Logger.getLogger("dbownership");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("===== SHARED DATABASE (anti-pattern) =====");
        AccountTable sharedTable = new AccountTable();
        SharedTransferService sharedTransfer = new SharedTransferService(sharedTable);
        SharedStatementService sharedStatement = new SharedStatementService(sharedTable);
        sharedTransfer.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        // statement reads the SAME table directly — tight coupling, no isolation.
        sharedStatement.printBalance("SAV2001");

        log.info("===== DATABASE-PER-SERVICE =====");
        EventBus bus = new EventBus();
        AccountService accountService = new AccountService(bus);     // owns accountdb
        StatementService statementService = new StatementService();   // owns statementdb
        bus.subscribe(statementService::onAccountChanged);            // event boundary

        accountService.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        // statement reads its OWN local read model, updated by the event (eventual consistency).
        statementService.printBalance("SAV2001");
    }
}

// ─── shared/AccountTable.java — one table, many writers (anti-pattern) ───
class AccountTable {
    final Map<String, BigDecimal> balances = new HashMap<>();
    AccountTable() { balances.put("SAV2001", new BigDecimal("1000000"));
                     balances.put("CUR3001", new BigDecimal("250000")); }
}

// ─── shared/SharedTransferService.java ───
class SharedTransferService {
    private static final Logger log = Logger.getLogger("dbownership");
    private final AccountTable table;   // writes the shared table directly
    SharedTransferService(AccountTable table) { this.table = table; }
    void transfer(String from, String to, BigDecimal amt) {
        table.balances.put(from, table.balances.get(from).subtract(amt));
        table.balances.put(to, table.balances.get(to).add(amt));
        log.info(() -> "[SHARED] transfer done, wrote accounts table directly");
    }
}

// ─── shared/SharedStatementService.java ───
class SharedStatementService {
    private static final Logger log = Logger.getLogger("dbownership");
    private final AccountTable table;   // reads the SAME shared table — coupling
    SharedStatementService(AccountTable table) { this.table = table; }
    void printBalance(String id) {
        log.info(() -> "[SHARED] statement reads shared table: " + id + " = Rs." + table.balances.get(id)
                + "  (coupled: a schema change here breaks the transfer service too)");
    }
}

// ─── account/AccountChangedEvent.java ───
class AccountChangedEvent {
    final String accountId; final BigDecimal newBalance;
    AccountChangedEvent(String accountId, BigDecimal newBalance) {
            this.accountId = accountId;
            this.newBalance = newBalance;
    }
}

// ─── account/AccountDb.java — PRIVATE to AccountService ───
class AccountDb {
    final Map<String, BigDecimal> balances = new HashMap<>();
    AccountDb() { balances.put("SAV2001", new BigDecimal("1000000"));
                  balances.put("CUR3001", new BigDecimal("250000")); }
}

// ─── account/AccountService.java — owns its data, publishes events ───
class AccountService {
    private static final Logger log = Logger.getLogger("dbownership");
    private final AccountDb db = new AccountDb();   // nobody else may touch this
    private final EventBus bus;
    AccountService(EventBus bus) { this.bus = bus; }
    void transfer(String from, String to, BigDecimal amt) {
        db.balances.put(from, db.balances.get(from).subtract(amt));
        db.balances.put(to, db.balances.get(to).add(amt));
        log.info(() -> "[ACCOUNT-SVC] transfer committed in OWN db (strong consistency)");
        // publish facts; other services learn via events, not by reading our DB
        bus.publish(new AccountChangedEvent(from, db.balances.get(from)));
        bus.publish(new AccountChangedEvent(to, db.balances.get(to)));
    }
}

// ─── statement/StatementReadModel.java — PRIVATE to StatementService ───
class StatementReadModel {
    final Map<String, BigDecimal> view = new HashMap<>();
}

// ─── statement/StatementService.java — owns its own read model ───
class StatementService {
    private static final Logger log = Logger.getLogger("dbownership");
    private final StatementReadModel readModel = new StatementReadModel();
    void onAccountChanged(AccountChangedEvent e) {
        readModel.view.put(e.accountId, e.newBalance);   // update local copy from event
        log.fine(() -> "[STATEMENT-SVC] read model updated " + e.accountId + " = Rs." + e.newBalance);
    }
    void printBalance(String id) {
        BigDecimal v = readModel.view.get(id);
        log.info(() -> "[STATEMENT-SVC] reads OWN read model: " + id + " = Rs." + v
                + "  (eventually consistent; decoupled from account-service schema)");
    }
}

// ─── bus/EventBus.java — stand-in for Kafka ───
class EventBus {
    private final List<Consumer<AccountChangedEvent>> subs = new ArrayList<>();
    void subscribe(Consumer<AccountChangedEvent> s) { subs.add(s); }
    void publish(AccountChangedEvent e) { subs.forEach(s -> s.accept(e)); }
}

// ─── BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tH:%1$tM:%1$tS %2$-7s %3$s%n",
                new Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
